function LEVEL_LABELS(succ, root, k):
    level <- [root]
    repeat k times:
        next <- empty list
        for each label a in level:
            next <- next ++ succ(a)
        level <- next
    return level

function LEVEL_COUNT(succ, root, k):
    return length(LEVEL_LABELS(succ, root, k))

function VERIFY_ISO(succ1, succ2, phi, root1, root2, reachable):
    if phi(root1) != root2:
        return FALSE
    for each label a in reachable:
        if succ2(phi(a)) != map(phi, succ1(a)):
            return FALSE
    return TRUE
